style.css:
@-moz-document domain("google.com") {
/* Hide Google logo */
  #hplogo, img[alt="Google"], svg[aria-label="Google"] {
    display: none !important;
  }

  /* Add your custom name */
  body {
    position: relative !important;
  }

  body::before {
    content: "KIPRONO DAN";
    position: absolute;
    top: 150px;
    left: 50%;
    transform: translateX(-50%);
    font-size: 92px;
    font-weight: bold;
    font-family: 'Product Sans', Arial, sans-serif;
    color: #4285F4; /* Blue like Google’s first letter */
  }
}
